values.value:
{
  "ShowcaseEventType": {
    "required": ["eventType"]
  },
  "ShowcaseSchedule": {
    "pageValidators": [
      { "validator": "validateSessionMin", "message": "Please select at least one session slot." }
    ]
  },
  "ShowcasePreferences": {
    "required": ["dietaryOption", "shirtSize"]
  },
  "ShowcaseContact": {
    "required": ["firstName", "lastName", "email", "phone"],
    "patterns": {
      "phone": "\\+?[0-9]{9,15}"
    },
    "validators": {
      "email": ["validateShowcaseEmail"]
    },
    "hints": {
      "phone": "International format accepted, e.g. +359888123456",
      "email": "A confirmation will be sent to this address"
    },
    "if (hearAboutUs='referral')": {
      "required": "referralName"
    },
    "if (not(hearAboutUs='referral'))": {
      "hidden": "referralName"
    }
  },
  "ShowcaseSummary": {
    "navigationByChild": true,
    "required": ["agreeGdpr"]
  }
}
